; ints.asm -- chapter 16: WHERE IT BREAKS: the interrupts come back
; generated by gen16.py
        INCLUDE "msx.inc"
        OUTPUT "ints.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; WHERE IT BREAKS. The program keeps the interrupts off, as every program in
; this book has since chapter 5, and times the same loop before and after a
; single call of CHPUT.
init:   di
        ld sp, SYS_AREA
        im 1
w1:     call wait               ; two frames, priced
w2:     ld a, 'A'
        call CHPUT              ; one character, through the BIOS
w3:     call wait               ; the same two frames again
w4:     nop
stop:   jr stop

; wait: 4,757 turns of chapter 14's loop. Uses A, DE.
wait:   ld de, 4757
wt:     dec de
        ld a, d
        or e
        jr nz, wt
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
